/* Private, original campaign preparation. No chapter is an event or a player handout. */
(() => {
  'use strict';
  const source='The Echo Below: approved Campaign Outline and Questbook character chains; original playable staging. Future possibilities, not confirmed play. Published dungeon room keys remain authoritative.';
  const E=(observed=[],claimed=[],inferred=[],open=[])=>({observed,claimed,inferred,open});
  const N=(name,motive,knows,wants,limits)=>({name,motive,knows,wants,limits});
  const S=(title,read,run,choices,evidence,consequences,fallback,checks=[],npcs=[])=>({title,read,run,choices,evidence,consequences,fallback,checks,npcs});
  const C=(character,n,title,stage,trigger,summary,scenes,connections,reward,declined,limits)=>{
    const questId='character-'+character,stepId=questId+'-'+n,id='chapter-'+stepId;
    return {id,characterId:'pc-'+character,questId,stepId,title,stage,trigger,summary,scenes:scenes.map((s,i)=>({id:id+'-'+(i+1),...s})),connections,reward,declined,limits,source};
  };
  const chapters=[
    C('trista',1,'An Old Partner’s Warning','waterdeep',
      'After a real Waterdeep arrival and Mara has a credible source for a buyer’s search. No source establishes who holds the BELOW token unless play did.',
      'A private warning and a modest job let Trista decide how much contact she wants with Mara.',[
      S('The warning at a quiet table','Mara turns a folded commission so only you can read it. “They are asking after something marked BELOW. I know what they want. I do not know who has it.”',
        'Use Red Sash or a quiet Portal table. Before play, choose a source Mara could actually access: a dated broker circular or a request delivered to her. Show only its object description. Her offered job is to verify a buyer’s storage claim, with a fee and safe exit agreed first.',
        ['Ask for the circular and its route to Mara.','Hear the job while revealing nothing.','Set a boundary: no questions about possessions and no approach to companions.'],
        E(['The commission describes a marked dark stone, if examined.'],['Mara says a buyer is asking after it.'],['Someone values the object; the reason is unproved.'],['Who wrote the commission, and who has seen it?']),
        ['A permitted copy creates a traceable lead.','A boundary gives Mara a concrete promise she can later keep or breach.'],
        'If Trista declines contact, Mara leaves one requested method for future contact and withdraws. A broker invoice can surface through ordinary research.',
        ['No check forces disclosure. Investigation DC 12 can identify a reused invoice number faster; the visible wording is available without a roll.'],
        [N('Mara Vey','Keep a working relationship and avoid an unsafe buyer.','Only the circular and her own instructions.','A discreet answer about the buyer’s reliability.','She does not know Trista has the token, its powers, or Halaster’s plan unless told.')]),
      S('A job with an exit','“No delivery tonight,” Mara says. “We check the address, learn what is being offered, and leave. Tell me the line you will not cross.”',
        'Offer a lawful inspection of public receipts or an appointment with the broker. Trista may bring a companion under an agreed cover that requires no lie about the token. A clerk can confirm receipt and recipient without revealing the object’s current location.',
        ['Take the inspection with written limits.','Ask Mara to obtain consent for a records copy.','Decline the work but keep the warning.'],
        E(['A receipt or meeting time can be compared with Mara’s circular.'],['The clerk says the buyer handles research acquisitions.'],['Matching references may link two transactions.'],['What conditions were omitted from the offer?']),
        ['A completed bounded task can earn the agreed fee and one reliable contact after review.','No-show or refusal changes the proposed job, not ownership of the token.'],
        'A public copy, former clerk, or later legitimate inspection supplies the same transaction lead; no unseen theft follows refusal.',
        ['Use Stealth only for an actually concealed approach; offer an open appointment with a slower timetable.'],
        [N('Broker’s records clerk','Complete a defensible transaction without personal trouble.','The recorded client reference and submitted terms.','Proof of permission before providing private papers.','Does not know the token’s keeper or the buyer’s ultimate motives.')])
      ],{city:['Red Sash','Yawning Portal'],dungeon:['Ordinary return after The Missing Instrument'],sites:[],mystery:['echo-observable']},
      'A verified warning, negotiated job terms and a chosen degree of contact; payment only if agreed work is delivered.',
      'Offer a different practical task or leave Mara available by Trista’s chosen contact method. Her personal quest can remain deferred.',
      ['The BELOW token remains distinct from Echo’s Whisper.','Mara cannot infer possession from secrecy; no forced confession or betrayal.']),

    C('trista',2,'The Missing Terms','waterdeep',
      'After Trista accepts a follow-up or an actual invoice brings the Still Hand acquisition broker within reach.',
      'Compare the offer against an independent record before deciding what Mara knew and what she withheld.',[
      S('Two copies of the offer','The second copy has a line missing from the first: delivery includes permission for a suppression examination. The signatures do not explain who removed it.',
        'Prepare two separately held copies with dates and provenance. The broker wants artifacts isolated; Mara’s knowledge is a question to establish from her received copy and replies. Do not decide she knowingly deceived Trista simply because the terms differ.',
        ['Compare versions with Mara present.','Ask the clerk privately when the clause was added.','Stop the transaction until everyone receives the same terms.'],
        E(['The two inspected copies differ.'],['The clerk or Mara gives an account of which version they received.'],['Someone may have changed the offer after circulation.'],['Who authorized the clause, and when did Mara learn of it?']),
        ['A dated receipt can exonerate or implicate a specific act without settling every motive.','Pausing a job preserves custody while delaying payment.'],
        'If either original is lost, compare a dispatch ledger with the recipient’s dated notes. An unavailable witness leaves the timing unresolved.',
        ['Investigation DC 13 can sequence physical edits; basic differences are plain. Insight identifies hesitation, not guilt or hidden facts.'],
        [N('Still Hand acquisition broker','Limit uncontrolled circulation of resonant objects.','The broker’s own examination requirement and delivery chain.','Consent to an isolation assessment under agreed terms.','Cannot speak for every Still Hand member or name Halaster as employer without evidence.')]),
      S('Ask for the whole bargain','Mara listens until you finish. “Then ask me exactly. I can tell you what I was paid to do, what I guessed, and what I was afraid to ask.”',
        'Let Trista question Mara about one dated omission, then hear a separate witness. If Anja is approached, she can explain her own isolation principles while acknowledging that she did not supervise this purchase. Offer a revised contract with no transfer until consent.',
        ['Continue with explicit examination limits and a neutral witness.','Refuse the broker while keeping Mara as a friend or contact.','End the relationship or request distance.'],
        E(['The parties state specific terms and boundaries.'],['Mara explains her knowledge and incentive.'],['The buyer’s link to the Still Hand is supported only by checked records.'],['Will either party honor the revised limits?']),
        ['Record only promises actually made and who heard them.','Anja’s care remains available without requiring faction allegiance.'],
        'Trista can send written limits through an intermediary; no face-to-face confrontation is required.',
        ['Persuasion may improve a negotiable fee or timetable; it cannot compel a confession or consent.'],
        [N('Mara Vey','Keep her livelihood and a relationship she values.','Her own received terms, actions and omissions.','A decision about future work she can act on.','Her account needs independent checking; friendship does not grant access to possessions.')])
      ],{city:['Red Sash','Lantern House'],dungeon:['Skullport broker business only along an earned route'],sites:[],mystery:['district-interventions']},
      'A documented broker link and a relationship decision with clear terms; no automatic faction alliance.',
      'The transaction can remain suspended. An independent investigator can later report the records with source limits.',
      ['The broker is not automatically Halaster’s agent.','Do not merge Mara’s employer with Ringgo’s contact or invent their knowledge of one another.']),

    C('trista',3,'A Pattern in the Dark','depths',
      'At an actually reached resonance site, after a player chooses to examine a legitimate observation. Stage one bounded test, not a new token power.',
      'A private comparison makes careful observation useful while preserving Trista’s choice about disclosure.',[
      S('The comparison she permits','The chalk line gives you something to compare: one mark, one fixed lamp, and the same place viewed twice. You can stop before anyone touches what you brought.',
        'Ask Trista what may be examined and by whom. Compare a voluntarily shown sketch or object with a known site pattern. If the token is private, use a public rubbing instead. Specify the predicted visible or measured difference before testing; retain a no-change result.',
        ['Use only an anonymous drawing.','Permit a witnessed examination without handing anything over.','Skip the test and inspect an independent record.'],
        E(['The recorded comparison, including no observable response.'],['An observer proposes an explanation.'],['Similarity suggests a line of inquiry, not a common maker or a transport link.'],['Does the effect recur with a control and a different observer?']),
        ['The result can open a research question with exact audience choices.','No result adds a class feature, curse or compulsory obligation.'],
        'A recovered survey and another crew’s measurements allow the same investigation without the token.',
        ['Arcana DC 13 can identify a useful control; the described observation remains available on failure.'],
        [N('Independent site examiner','Obtain a useful comparison without losing permission.','The measurements they personally perform.','A clear record of method and limits.','Cannot identify the token’s owner from an anonymous drawing or infer its full history.')]),
      S('Two accounts of one shadow','The witness describes the edge before you show your sketch. It matches one detail and disagrees on another. Neither account has to disappear to make the page tidy.',
        'Collect accounts separately, then compare. At the Silent Library, use a copied margin or an access discrepancy; in Undermountain, keep the actual room feature and route. Let Trista inspect a physical access point using her current abilities without tying Shadow powers to the Echo.',
        ['Preserve both accounts and plan a repeat.','Publish the shared observation while keeping the object private.','Ask the witness to withhold their interpretation pending review.'],
        E(['Separately recorded accounts agree and differ on named details.'],['Each observer offers a reason for the difference.'],['Changed conditions, memory or reconstruction remain competing explanations.'],['What measurement would distinguish those explanations?']),
        ['A disagreement generates a practical next investigation.','The witness may decline anonymity or publication; record the actual permission.'],
        'If no witness participates, keep one observation marked uncorroborated and offer a later ordinary research visit.',
        ['Investigation can reduce time locating a documented access mark; a single failed roll never deletes the only clue.'],
        [N('Site custodian or expedition witness','Protect access and avoid a misleading public account.','One visit and its conditions.','Credit and a chance to correct their words.','Their account is not independent if copied from Trista’s description.')])
      ],{city:['Second Margin','Ninepin Works'],dungeon:['Use a known research fragment or surveyed passage'],sites:['wave-echo','silent-library'],mystery:['echo-observable','glass-contradictions']},
      'A useful, bounded observation and an investigation that can proceed with or without personal disclosure.',
      'Keep the token private. Offer scouting, access checks or another character’s authorized sample as the practical contribution.',
      ['No essential conclusion requires the BELOW token.','Do not equate magical darkness, Shadow class abilities or a double shadow with proven causation.']),

    C('trista',4,'Terms of Trust','depths',
      'When an actual discovery has several interested custodians, or a current agreement needs revision after a concrete change.',
      'Negotiate custody, copying and emergency access without making public disclosure the required answer.',[
      S('Four spaces on the table','The custodian lays out four blank cards. “Who holds it? Who may inspect it? What may be copied? When do we ask again?”',
        'Choose an object or record actually recovered. Invite current holder, affected people and willing researchers. Each proposal must specify one benefit and one cost: secured original with slower access, witnessed visits, a warning-only copy, or community custody. Use Trista’s preferred privacy level.',
        ['Keep the original private and circulate a checked warning.','Share access with two independent witnesses and a withdrawal clause.','Return the discovery to an affected custodian with a later review.'],
        E(['The inventory and agreed access terms.'],['Each person states a need and a feared consequence.'],['A custody plan may reduce a named risk; it does not prove safety.'],['Who can stop use if a limit is breached?']),
        ['Approved terms become promises and custody records, not a permanent moral score.','Refusal may limit a specific service, not erase unrelated friendships.'],
        'A simple witnessed verbal agreement is enough. If no object was recovered, use access to a copy or route notes.',
        ['No roll overrides ownership or a person’s right to refuse. Negotiable storage costs can be discussed openly.'],
        [N('Affected custodian','Keep a real discovery from becoming an uncontrolled experiment.','Their current storage and access arrangements.','An enforceable limit and an emergency contact.','Cannot claim the party’s discoveries merely by declaring expertise.')]),
      S('A request outside the terms','A message arrives asking for a copy before the agreed review. It names a real need and leaves one important question unanswered: who else will receive it?',
        'Use a genuine new circumstance, such as a researcher departing or a resident seeking a warning. The requester has no automatic malicious intent. Let Trista verify urgency through a second contact and propose a smaller disclosure or a temporary exception.',
        ['Grant a narrow, recorded exception.','Offer a supervised viewing or warning without methods.','Keep the limit and arrange another way to meet the need.'],
        E(['The written request and any verified urgency.'],['The requester names their intended audience.'],['The exception’s risk depends on what is copied and retained.'],['Will the recipient agree to deletion, correction or further consent?']),
        ['Record actual recipients and promises before publication.','A refused exception can preserve trust when the reason and alternative are honest.'],
        'If Trista avoids the negotiation, another willing custodian can handle logistics under the existing limits; do not transfer ownership by silence.',
        ['Investigation DC 12 may confirm a dispatch deadline quickly; time pressure cannot force a decision.'],
        [N('Requesting researcher or neighbor','Meet a time-sensitive practical need.','Their own problem and recipients.','An answer they can use, even if narrower than requested.','Does not know private character history unless it was shared.')])
      ],{city:['Mending Court','Second Margin','Lantern House'],dungeon:['An actual return with disputed research custody'],sites:['silent-library','walking-tower'],mystery:['district-interventions','glass-restoration']},
      'A workable trust agreement with named limits and a procedure for disagreement.',
      'Preserve existing custody and offer another person’s voluntary administrative help. The chapter may close with a deliberately deferred decision.',
      ['No party vote controls Trista’s personal disclosures.','A missing log entry is a discrepancy, not proof of theft by Mara or a companion.']),

    C('trista',5,'The Keeper’s Choice','resolution',
      'After enough actual custody decisions and intervention evidence to offer a lasting arrangement; no finale outcome is assumed.',
      'Choose what responsibility to carry and what relationship with Mara to continue.',[
      S('What the arrangement leaves behind','The storage place is ordinary in daylight. There is room for a label, a second key, or nothing at all. The next choice is about who will answer when someone asks to use it.',
        'Review the real inventory, unresolved dangers and promises. Offer personal stewardship, shared custody, return, restricted archiving or a tested relinquishment procedure. Any destruction or shutdown needs a verified safe method and the actual holders’ agreement.',
        ['Keep custody with review and an independent stop condition.','Share stewardship and retain a right to withdraw.','Hand responsibility over through a witnessed transfer.'],
        E(['Current inventory, tested limits and named recipients.'],['Proposed custodians state what they will do.'],['Past kept promises support trust but cannot guarantee future behavior.'],['What event requires reopening the decision?']),
        ['A reviewed transfer updates custody and only the audiences chosen.','The ending can preserve privacy while changing access responsibly.'],
        'If the larger mystery remains open, agree a temporary arrangement and a review date rather than demand a final answer.',
        ['No final persuasion test selects the correct keeper. Technical shutdown checks use an already tested plan.'],
        [N('Chosen successor or co-custodian','Maintain useful access without repeating known harm.','The evidence and limits actually shared.','A sustainable responsibility they can refuse.','Cannot promise perfect safety or claim universal consent.')]),
      S('Mara’s next invitation','Mara sets down a new offer without reaching for your things. “This time, I wrote the terms first. You can still say no.”',
        'Use Mara’s actual behavior. If she respected limits, offer a modest future job; if she breached them, offer accountability without assuming reconciliation. Trista can continue friendship, restrict work, ask for distance, or decline contact. Close on one practical consequence of her chosen form of trust.',
        ['Accept a relationship with specific limits.','Ask for restitution or proof before further work.','Part without hostility, or choose no further contact.'],
        E(['The promises actually kept, broken or repaired.'],['Mara describes what she wants next.'],['A changed practice can support cautious confidence.'],['What future contact, if any, does Trista permit?']),
        ['Record the relationship separately from artifact custody.','A quiet ending can be complete without revealing the BELOW token to everyone.'],
        'If Mara never entered play, use an existing trusted contact and leave the unused relationship unestablished.',
        [],[N('Mara Vey','Find a future she can sustain with or without Trista’s work.','Only the relationship and disclosures that actually happened.','A clear answer rather than assumed forgiveness.','Cannot purchase reconciliation with a reward.')])
      ],{city:['Mending Court','Red Sash'],dungeon:['After the chosen Looking Glass intervention or a smaller settled dispute'],sites:[],mystery:['district-interventions']},
      'A chosen responsibility and relationship outcome reflected in an ordinary future scene.',
      'Close the current chapter through another actual act of trust or care. Personal secrecy is not a failed ending.',
      ['Do not presume token disposal, disclosure, forgiveness or a romantic relationship.','No magical corruption or ownership test decides her character.']),

    C('pebble',1,'A Familiar Maker’s Mark','waterdeep',
      'During The Missing Instrument, or when a legitimate object, receipt or sketch bears a mark the hammer-makers can examine.',
      'Turn a familiar mark into a checkable lead while preserving the missing craftsperson’s open identity and fate.',[
      S('The mark under the repair','Beneath a newer repair, a small tool mark resembles the one on your hammer. Orren sets the object down. “Similar work. Shall we find out how similar?”',
        'Use the already placed instrument or a permitted drawing; do not add an item to a cleared room. Compare geometry, spacing and wear without declaring the maker. Give Pebble a safe handling role and ask whether he wants to contact the dwarves who made his hammer.',
        ['Make a rubbing with the owner’s permission.','Ask Orren for the repair history.','Keep a description and continue the paid job first.'],
        E(['The two visible marks share specified features.'],['Orren calls the workmanship familiar.'],['A common workshop is possible; a copied mark remains possible.'],['Can the hammer-makers identify a specific hand or commission?']),
        ['A recorded comparison opens correspondence without fixing a name.','The object remains with its actual owner until a reviewed transfer.'],
        'If the instrument was lost, its purchase drawing or a separate workshop receipt carries the comparison.',
        ['Smith’s tools or Investigation DC 12 distinguishes an old mark from a recent repair; resemblance itself is visible.'],
        [N('Orren Brassmantle','Recover useful equipment and reliable repair knowledge.','His purchase and maintenance records.','Permission to compare marks and contact the maker.','Does not know the colleague’s fate or Pebble’s mountain home unless told.')]),
      S('An answer from home','The reply begins with something ordinary about work at the forge. Then the writer turns to your sketch: “We know the habit of that chisel. We have not had an answer to our last letter.”',
        'Let Byron supply names or keep the writers as hammer-makers. Their dated commission book can establish that a colleague used the mark. The last unanswered letter proves a lapse in contact, not kidnapping or death. Include a known intermediary or forwarding address as a lead.',
        ['Request the last confirmed commission and contact.','Send a friendly message before assuming danger.','Ask someone experienced to help plan the unfamiliar route.'],
        E(['A dated workshop entry matches a distinctive mark.'],['The makers report unanswered correspondence.'],['Their colleague may be missing, delayed or avoiding contact.'],['Why did the colleague leave, and who last saw them?']),
        ['A checkable contact advances the investigation.','Asking for navigation help is a competent choice, not a confidence failure.'],
        'If Pebble does not write, a consenting workshop associate can identify the mark at an ordinary city visit.',
        ['No check is required to ask for help or receive a legible reply.'],
        [N('Pebble’s hammer-makers','Know their colleague is safe and maintain their own work.','Their own commissions and last exchange.','A reply or reliable account without reckless rescue.','Their names, home details and colleague’s identity remain player-established.')])
      ],{city:['Ninepin Works','Mending Court'],dungeon:['The Missing Instrument; compatible earned route only'],sites:['wave-echo'],mystery:['echo-observable']},
      'A verified workshop connection, a contact to pursue, and a copy Pebble may take home.',
      'Keep the reply available. A new legitimate mineral commission can develop navigation and craft interests without a missing-person hook.',
      ['Do not name or kill the missing craftsperson by default.','No automatic weapon improvement, magic identification or required tasting.']),

    C('pebble',2,'The Missing Craftsperson','depths',
      'After a verified workshop lead and access to an actual city associate or reachable dungeon workshop.',
      'Establish why the colleague left and what help is wanted before choosing a rescue story.',[
      S('The last paid job','The ledger lists wages, a delivery, and a travel advance. The line after the advance is blank. The keeper says, “Leaving was their choice. What happened afterward, I cannot tell you.”',
        'Choose a workshop compatible with the known route and inhabitants. Prepare a paid commission to inspect unusual material, a dated departure entry, and an associate who witnessed one part. Keep location and identity open until staged. Give a concrete return condition before any descent.',
        ['Compare the ledger with a receipt held elsewhere.','Ask what material and tools the colleague took.','Send a message along the established route before traveling.'],
        E(['The signed advance and independently held receipt, if examined.'],['The associate says the colleague left willingly.'],['A mineral commission may explain the journey.'],['Was the arrival recorded, and are they still there?']),
        ['Checked records narrow a route without resolving the fate.','An honest partial report can satisfy an information request.'],
        'If the workshop is inaccessible, use a supplier’s copy and a consenting messenger; the lead does not require clearing an unrelated floor.',
        ['Investigation DC 13 saves time reconciling trade dates; an accessible core receipt remains findable.'],
        [N('Workshop associate','Settle unpaid work and avoid sending another person into danger.','The departure and goods they personally handled.','A reliable contact plan and account of the commission.','Cannot know events after departure or rewrite Melairkyn history.')]),
      S('A question before a rescue','A reply, witness, or abandoned work note gives you a task more precise than “find them”: learn whether a safe return is possible and what must be left behind.',
        'Before staging, select the branch supported by discoveries: living and needing help, voluntarily absent, displaced, or fate still unknown. Do not choose a death for dramatic force. A living colleague chooses whether to return. An incomplete record can instead identify a useful safe-contact point.',
        ['Offer an escort with a planned exit and shared navigation.','Carry a message while respecting voluntary absence.','Report the uncertainty and defer the dangerous leg.'],
        E(['The actual message, meeting or physical trace.'],['A witness’s account of the colleague’s present need.'],['A practical return may be possible if specific hazards are addressed.'],['What does the colleague want preserved, and who owns it?']),
        ['Delivering a true account can resolve the family’s immediate request.','An escort creates actual route and supply decisions; it grants no safe corridor automatically.'],
        'If the colleague never enters play, bring back their authorized work or a confirmed message rather than inventing a reunion.',
        ['Use actual room hazards and travel checks; bypass, negotiation and retreat remain available.'],
        [N('Missing craftsperson, identity to be established','Continue or leave their work on their own terms, if alive.','Their own journey and commission.','A specific form of help rather than compulsory rescue.','Survival, location, shared history and willingness to return remain unresolved until prepared and played.')])
      ],{city:['Ninepin Works','Reed & Ledger'],dungeon:['A known workshop or current custodian on an earned route'],sites:['silent-library','observatory'],mystery:['echo-observable']},
      'A reliable account, a chosen assistance plan and craft knowledge earned by consent.',
      'Let a trusted messenger continue the inquiry; Pebble may focus on present companions while keeping a future reply open.',
      ['No mandatory relative, disappearance, death or rescue success.','A workshop contact does not overwrite a published room’s inhabitants or history.']),

    C('pebble',3,'Stone That Doesn’t Belong','depths',
      'A sample is legally and safely available with a recorded origin; use actual mine, workshop or satellite access.',
      'Separate material familiarity from provenance and test a limited practical use.',[
      S('The sample and the label','Two pieces look almost alike. One has a place, date, and collector written beside it. The other has only a price. Which question do you want answered first?',
        'Provide two modest inert samples with permission. One known local comparison prevents every unusual stone becoming magical. Pebble can describe texture and working behavior; a specialist can test composition. Unknown material is never a mandatory snack.',
        ['Compare weight, fracture and tool response without ingestion.','Trace the unlabelled seller’s source.','Ask the owner to keep both samples until a safe method is agreed.'],
        E(['Recorded physical properties and handling conditions.'],['A seller names an origin or unusual effect.'],['A material difference may suggest import, alteration or mixed provenance.'],['Can an independent collection confirm the origin?']),
        ['A careful label makes the observation usable to later researchers.','A mundane explanation is a successful finding, not a wasted hook.'],
        'If no sample may leave the site, use supervised observation, a sketch and a small approved test in place.',
        ['Relevant tools or Nature DC 13 distinguish composition; failure leaves the sample unidentified, not secretly dangerous.'],
        [N('Mineral custodian','Preserve stock or a threatened local resource.','Where their own samples were collected.','Credit, safe handling and agreed return.','Cannot identify unknown divine or planar origins by appearance alone.')]),
      S('A boundary small enough to test','The test tray is no wider than your hands. “We compare this much first,” Orren says. “If it changes, we stop. A street is not a test tray.”',
        'Choose a question earned by the source: vibration isolation, visible instability, or a material discrepancy. Record prediction, control, stop condition and independent observer. A successful small comparison offers an engineering lead, not a finished district-scale shield.',
        ['Run the bounded test under the owner’s conditions.','Ask another craftsperson to repeat it separately.','Keep the finding as an unanswered question and stop.'],
        E(['The actual recorded trial and any negative result.'],['The examiner proposes a possible application.'],['The material might help a limited boundary under tested conditions.'],['Will the behavior persist with different loads and independent review?']),
        ['A reproducible result can support one later intervention research plan.','A failed prediction changes the plan without reducing Pebble’s worth.'],
        'Use existing measurements or refer the test to an independent workshop if the party does not want to experiment.',
        ['Tool checks concern setup quality and time. No single roll certifies a material safe for people.'],
        [N('Orren Brassmantle','Build a practical device with a known failure condition.','The trial method and instrument readings.','A repeatable result before promising a larger use.','Cannot certify district protection from one sample.')])
      ],{city:['Ninepin Works'],dungeon:['A recorded material comparison on the current expedition'],sites:['wave-echo','observatory','frozen-door'],mystery:['echo-observable','glass-contradictions','district-interventions']},
      'A provenance record and a tested question that may improve a real route or later safeguard.',
      'Offer a sketching or delivery role; an allied workshop can perform the comparison with reported uncertainty.',
      ['Mineral appetite is characterization, not a compulsory hazard.','No free hammer upgrade or universal anti-magic material is awarded.']),

    C('pebble',4,'Someone to Follow','depths',
      'A willing group needs a route through a genuinely surveyed hazard and Pebble wants a navigation role.',
      'Let ordinary route work protect people without requiring fearlessness or a solo test.',[
      S('Make a plan they can repeat','You place the route notes where everyone can see them. “If we lose sight of each other, we meet here.” The people listening ask you to show them how they will recognize it.',
        'Use an actual retreat path, cargo passage or optional site exit. List one known hazard, one unverified segment and a clear turnaround. Let Pebble choose partner, marks, pace and supply reserve. Other PCs contribute perception, translation or negotiation.',
        ['Lead with another navigator checking turns.','Teach the marks and let a local guide take the front.','Choose the longer verified route and leave the shortcut untested.'],
        E(['The survey, placed marks and rehearsal observed by the group.'],['A guide reports a changed segment.'],['A route is dependable only within the checked conditions.'],['Which marker or refuge needs a fresh inspection?']),
        ['A jointly understood return plan becomes an expedition resource.','Declining the shortcut may cost time while protecting reserves.'],
        'If nobody needs an escort, rehearse the party’s own retreat route or help Orenna plan a courtyard delivery.',
        ['Survival DC 12 can estimate time in known terrain; use actual terrain hazards for unverified sections.'],
        [N('Willing traveler or local guide','Reach a specific destination without abandoning their companions.','Their own needs and one route segment.','A plan they understand and can question.','Not a helpless prop; can decline an unsafe route.')]),
      S('The mark that moved','One familiar mark is still there. The next lies beside fresh rubble. The route has changed in one place, and you have time to choose what to do about it.',
        'Use a concrete cause supported by dungeon play: a collapse, a closed door, a posted toll or a witnessed alteration. Preserve the rest of the survey. Present a verifiable detour, negotiated passage or return to the last refuge; ask the group’s needs before moving.',
        ['Compare the change with the last dated survey.','Negotiate a supervised detour with its current keeper.','Return together and report the blocked section honestly.'],
        E(['The changed segment and unchanged reference marks.'],['A keeper explains their reason for closing passage.'],['The change has a local cause until broader evidence exists.'],['Who can restore or verify access, and at what cost?']),
        ['A successful withdrawal is a meaningful delivery of the plan.','Record the specific route state rather than clearing or invalidating the whole map.'],
        'If the path remains clear, use the occasion to teach a second group the marks and credit Pebble’s preparation.',
        ['No arbitrary navigation roll erases a known route. Checks resolve new information, pace or exposure.'],
        [N('Current passage keeper','Protect their territory or prevent a known hazard.','Their own closure and conditions for access.','A credible arrangement, warning or practical repair.','Cannot guarantee all downstream routes or demand the party’s secrets.')])
      ],{city:['Mending Court','Blue Lantern Quay'],dungeon:['Terms of Passage; actual persistent retreat route'],sites:['observatory','frozen-door','broken-star'],mystery:['district-interventions','district-coupling']},
      'A route people can use, a witnessed safe return or an honest hazard report that prevents harm.',
      'Co-navigation, logistical preparation or asking a better-equipped guide are equally valid contributions.',
      ['Fear need not disappear.','Travelers keep agency and no dependent person is killed solely to punish a declined spotlight.']),

    C('pebble',5,'A Map of His Own','resolution',
      'After real journeys provide useful notes; Tavin’s work is available only after its independent identity is earned.',
      'Decide what to take home, who may use the routes and how to honor another maker’s imperfect work.',[
      S('A place for the corrections','Your map has changed hands enough to show it: a repaired edge, a better turn, a warning added by someone who came back. There is space for another person’s correction.',
        'Gather only routes actually traveled or clearly marked as hearsay. Invite a traveler and a hammer-maker’s correspondent to check different parts. If Tavin’s map is known, compare one deliberate crooked detail with the corrected reconstruction as a craft observation, not a verdict on personhood.',
        ['Make a public safe-route copy with private refuges omitted.','Keep an annotated original and invite credited corrections.','Return the missing colleague’s authorized work to its chosen keeper.'],
        E(['Dated route corrections and the actual compared detail.'],['A traveler reports their experience.'],['An imperfect drawing may preserve an intention lost in a tidier copy.'],['Which places need permission before being included?']),
        ['Reviewed publication can help real explorers and establish a maintenance contact.','A corrected-model discrepancy supports a bounded research question only.'],
        'If no family evidence is available, complete an ordinary route book and leave that comparison for another chapter.',
        ['No cartography roll is required to value a useful, honest map. Checks may improve readability or reproduction time.'],
        [N('Map user or hammer-maker correspondent','Use the work without exposing private places.','Routes they have traveled and local needs.','A readable copy with dates and limits.','Does not know unknown sites merely because the Nine symbol has circles.')]),
      S('What goes home','There is room in the pack for a letter, a modest sample, and the map. Someone asks, “When they see this, what do you want them to know about the places you found?”',
        'Offer a visit, a message or a chosen local homecoming. Let Byron define any still-open mountain details. The missing colleague’s fate follows actual records. A return gift can be a permitted sample, repaired tool, paid commission or story; no powerful item is assumed.',
        ['Bring home useful knowledge and credit everyone who helped.','Invite the makers to visit a place Pebble now knows.','Keep traveling while promising a realistic way to stay in touch.'],
        E(['The delivered objects, letter and witnessed promises.'],['Recipients describe what would help them.'],['Confidence is shown by chosen actions, including asking for help.'],['What route or relationship does Pebble want to build next?']),
        ['A fulfilled promise can create an ordinary future commission or reciprocal visit.','His home and the Hollow Mountain remain separate unless Byron’s later choices connect them.'],
        'If a long journey is unwanted, arrange a local celebration or consenting courier and leave the mountain visit open.',
        [],[N('Pebble’s hammer-makers','Maintain their craft and hear from someone they care about.','What Pebble actually shares and their own work.','A dependable connection rather than proof he is fearless.','Cannot define his preferred future or secretly make his home a finale site.')])
      ],{city:['Mending Court','Ninepin Works'],dungeon:['Any actual completed survey'],sites:['silent-library'],mystery:['family-ilyra-tavin','glass-contradictions','district-interventions']},
      'A useful map, maintained relationships and a player-chosen sense of home.',
      'A small local route and a kept promise are enough to close the current chapter; a grand homecoming is optional.',
      ['Never preassign Hollow Mountain to Pebble’s home.','No compulsory cure for anxiety or assumption that the missing colleague survived.']),
    C('donavan',1,'A Question for Home','forge',
      'After a real observation worth discussing, during Phandalin recovery or a later quiet return. An earlier letter can concern an ordinary finding.',
      'Send Dianna one bounded question and let her mathematical work sharpen a test without solving the mystery remotely.',[
      S('One page, three columns','The page has room for what happened, what you think it means, and what would change your mind. The first column is shorter than the second.',
        'Use actual Forge notes, a legitimate sample record or a mundane comparison. Ask Donavan what he observed personally and what came from others. The letter can omit coordinates, names and private character material. Offer a clear dispatch method and estimated delay; this is in-app correspondence.',
        ['Send measurements and one testable question.','Send a personal letter first and hold the research back.','Ask permission before including another person’s observation.'],
        E(['The recorded observation and its conditions.'],['Any quoted witness account remains attributed.'],['The proposed relationship is a hypothesis.'],['Which observation would distinguish the hypothesis from coincidence?']),
        ['A saved draft preserves the intended audience and attachments.','A reviewed in-world dispatch creates a correspondence record, not an external message.'],
        'If Donavan does not write, let him keep a field note and consult a willing local expert; Dianna’s relationship need not be transactional.',
        ['No check is required to write clearly. Investigation can identify a missing control before the letter is sent.'],
        [N('Dianna Kemp, correspondent','Continue her own mathematical work and share a life with Donavan.','Only the observations and personal news he sends.','A tractable question and ordinary contact.','Does not know the token, family history or experiment unless the evidence is shared.')]),
      S('A question returned','Dianna’s reply includes news from her own work. In the margin she has written, “Try predicting the next interval before you measure it. A pattern should risk being wrong.”',
        'Have Dianna propose one modest method: compare recorded intervals, repeat an inert control, or have two observers write independently. She can challenge an assumption and admit missing information. Include an ordinary detail Donavan can answer so the marriage is not only a clue delivery system.',
        ['Agree a prediction and arrange a safe repeat.','Explain why the field conditions make that test impossible.','Ask Dianna to seek an independent comparison with limited data.'],
        E(['The letter proposes a specific prediction and method.'],['Dianna offers a mathematical interpretation.'],['A repeated result could support the relationship.'],['What uncontrolled factor could produce the same pattern?']),
        ['The reply can become a research project with no result filled in.','A corrected assumption can improve trust without embarrassing either researcher.'],
        'A delayed reply creates no stalled quest: use the independent-observer method from Donavan’s own notes, then compare when correspondence arrives.',
        ['Arcana can help identify a magical confound; it does not substitute for recording the actual test.'],
        [N('Dianna Kemp','Find an explanation that survives a contrary result.','The limits of the data she received and her own method.','A reported result, including failure, and a reply to her personal news.','She is neither an all-knowing hint source nor proof that the Archive controls the phenomenon.')])
      ],{city:['Mending Court','Ninepin Works'],dungeon:['First bounded survey or missing-instrument return'],sites:['wave-echo'],mystery:['echo-observable']},
      'A useful research question, a correspondence thread and a method another person can evaluate.',
      'Keep family correspondence personal; a field colleague can supply the technical comparison without replacing Dianna.',
      ['The Kemp Archive is in an elven metropolis, not the Feywild.','Do not invent a connection between Markus’s death and the Echo.']),

    C('donavan',2,'A Different Conclusion','waterdeep',
      'After there is a shareable observation and the DM has offered Donavan’s player a scholarly rival without fixing a name or past relationship.',
      'A credible rival presents evidence that can challenge an interpretation rather than manufacture a villain.',[
      S('The other notebook','The researcher places their notebook beside yours. “I believe your observation. I think your explanation predicts something mine does not. Shall we write both down?”',
        'Keep the rival a role until introduced. Their competing theory must fit actual data: local material effects versus shared resonance, or amplification versus the mechanism it serves. Give them one legitimate independent measurement and one uncertainty; no automatic knowledge of Looking Glass.',
        ['Compare source dates and methods before conclusions.','Exchange redacted notes with credit and a correction agreement.','Ask a neutral reviewer to describe the disagreement.'],
        E(['The rival’s dated measurement, once provenance is checked.'],['Each researcher’s explanation of the data.'],['Two theories may currently fit the same observation.'],['Which accessible result would separate their predictions?']),
        ['A fair disagreement creates a research lead and a relationship.','Refusing raw data may limit the comparison while preserving other cooperation.'],
        'If Donavan’s player rejects a recurring rival, use an anonymous reviewed paper or one-time specialist with the same testable objection.',
        ['Investigation DC 13 can spot a missing control; failure does not make the rival dishonest or remove the visible evidence.'],
        [N('Scholarly rival, identity to be established','Receive fair credit for a defensible explanation.','Their own observations and the material Donavan shares.','A discriminating test and acknowledgement if correct.','No established family conspiracy, secret employer or personal history.')]),
      S('Predictions before the result','Two folded slips lie beside the instrument. One names the expected change; the other names the expected absence. Neither can be rewritten after the reading.',
        'Agree a safe test location already accessible and a shared description of outcomes, including inconclusive. Use separate observers and mark whether the rival’s old measurement derives from the same source. Allow the party to choose scope and witnesses before travel.',
        ['Commit to a joint test with independent notes.','Run separate small tests and compare afterward.','Seek a third explanation rather than force a two-person contest.'],
        E(['The dated predictions and agreed method.'],['Each researcher states why their outcome would matter.'],['The test can distinguish only the stated versions of the theories.'],['What result would leave both explanations incomplete?']),
        ['A prepared research project records credit, access and publication limits.','An inconclusive result preserves both hypotheses and suggests a better method.'],
        'If the route is declined or unavailable, compare archived observations with explicit limitations instead of moving the test into an unsafe home.',
        ['No social roll forces someone to sign away credit or private data.'],
        [N('Neutral reviewer','Make the comparison legible and fair.','The agreed hypotheses and methods.','Separate records and permission to report disagreement.','Cannot guarantee either researcher’s honesty beyond observed conduct.')])
      ],{city:['Ninepin Works','Second Margin','Starcup Roof'],dungeon:['An actual anomalous room along the chosen expedition route'],sites:['silent-library','observatory'],mystery:['echo-observable','glass-amplifies']},
      'A test that can prove either researcher mistaken and a rival relationship built on actual conduct.',
      'Use a written critique or alternate examiner. Donavan can pursue the question without a competitive relationship.',
      ['The rival’s name, affiliations and shared past remain open.','Good-faith disagreement is not evidence of sabotage.']),

    C('donavan',3,'Repeat the Experiment','depths',
      'The group chooses a research visit with a defined question, safe method and legitimate access.',
      'Run a bounded experiment, record negative results and let independent review change the explanation.',[
      S('Read the stop condition aloud','Before the apparatus is touched, the observer reads the final line: “If this limit is crossed, we stop.” There is a place on the form for a result nobody predicted.',
        'Review prediction, controls, cost, time, consenting participants and stop conditions. Use inert samples or archived records first. No resident, memory or living subject becomes an expendable variable. The rival may conduct a parallel observation where the actual route allows.',
        ['Proceed with the bounded method and shared stop signal.','Reduce the scope to a non-invasive observation.','Postpone because an essential control or consent is missing.'],
        E(['The actual method, conditions and measurements.'],['Observers report what they directly perceived.'],['The result supports, challenges or fails to distinguish predictions.'],['Which uncontrolled conditions remain?']),
        ['Record only the result actually played through Outcome review.','Stopping responsibly can preserve equipment, access and trust without yielding a conclusion.'],
        'If the site is inaccessible, use two independently obtained records and label the conclusion weaker; the satellite remains optional.',
        ['Arcana or relevant tools DC 14 improves precision or reduces wasted time. A roll never substitutes for consent or declares an unsafe trial safe.'],
        [N('Site custodian','Protect people and continued access to the place.','The local limits they have actually observed.','A reversible method, repair plan and authority to stop.','Their caution may be reasonable even when a theory is promising.')]),
      S('The result that stays on the page','Your prediction and the reading remain side by side. The rival taps the discrepancy. “We should keep this part. It tells us what to ask next.”',
        'Compare independent notes before discussion merges memories. Permit either or both researchers to be wrong. If a Looking Glass discrepancy is already earned, separate amplification data from claims about identity. Decide who can repeat the test and what details can be shared.',
        ['Publish the bounded result with uncertainties and source credit.','Seek a repeat by someone not present.','Correct the hypothesis and retain the failed prediction.'],
        E(['The separate notes and discrepancy between prediction and result.'],['Each researcher offers a revised account.'],['A repeat may strengthen a narrow finding, not an entire theory.'],['Does the result generalize beyond this place and scale?']),
        ['A correction can earn a reviewer’s respect through honesty.','Independent review may narrow a proposed intervention rather than unlock a guaranteed device.'],
        'If the result is inconclusive, keep the method and arrange a simpler observation; research progress can be identifying what cannot yet be claimed.',
        ['No roll decides which theory the DM prefers. Compare the actual prediction to the actual outcome.'],
        [N('Scholarly rival','Leave a defensible record even if personally mistaken.','Their measurements, not another observer’s private experience.','Credit for useful work and a fair chance to revise.','Cannot dismiss contrary data solely because Donavan collected it.')])
      ],{city:['Ninepin Works','Second Margin'],dungeon:['A bounded research visit preserving published inhabitants and hazards'],sites:['silent-library','observatory','scar'],mystery:['glass-amplifies','glass-contradictions','district-interventions']},
      'A reproducible result, useful failed test or well-defined uncertainty that improves a later decision.',
      'Commission a small independent comparison, audit an existing dataset, or leave the question open without blocking the main investigation.',
      ['No compulsory living test subject or dangerous experiment in someone’s home.','Repeated copies of one account are not independent corroboration.']),

    C('donavan',4,'Who Needs to Know?','depths',
      'After a useful verified finding and a concrete audience need exist. Threatened-district details require actual supporting evidence.',
      'Separate urgent warnings, reproducible methods and personal identities into distinct publication decisions.',[
      S('Three requests for one report','Three requests arrive: residents ask what to watch for, a sponsor asks how to reproduce the result, and a colleague asks for the complete record. They are not asking for the same thing.',
        'Use current facts, not future revelations. Prepare a warning sheet, technical appendix and protected witness list as separate drafts. Give each requester a practical motive: safety, funding accountability, or independent review. Let Dianna comment without deciding for Donavan.',
        ['Release a useful warning without hazardous methods or private names.','Offer supervised technical review with participant consent.','Delay a conclusion while sharing what uncertainty means for safety.'],
        E(['The verified finding and requests actually received.'],['Each requester states why they need the information.'],['Different audiences may need different levels of detail.'],['Would a redaction hide a fact necessary for informed consent?']),
        ['A draft can be sent to one owner, chosen recipients or party only after explicit review.','A cautious warning still needs enough detail for residents to act.'],
        'If no broad threat is known, use a smaller dispute over survey data or a workshop result; do not invent a catastrophe deadline.',
        ['Insight can clarify a stated concern, not expose a hidden faction as fact.'],
        [N('Resident representative','Help neighbors make informed choices.','Their observed local problem and available assistance.','An understandable warning with practical steps and uncertainties.','Cannot consent for every household or demand private character records.'),N('Research sponsor','Account for funding and evaluate possible use.','The agreed contract and submitted results.','Enough method detail to judge whether further work is worthwhile.','Payment does not grant rights absent from the actual agreement.')]),
      S('The sentence that might harm someone','A reviewer circles a sentence. “This names a person who agreed to speak privately. Can you make the useful part true without making them a target?”',
        'Ask the affected witness, not just the researchers, about publication. A source may permit an anonymized account, insist on being named, or decline. Compare whether redaction obscures independence or useful limits. Offer separate public and restricted versions with revision dates.',
        ['Use an agreed description and protected provenance.','Seek another independent source for the public claim.','Remove the unsupported conclusion and publish the question instead.'],
        E(['The witness’s publication permission and any checked corroboration.'],['The reviewer identifies a concrete possible harm.'],['A redaction can protect someone while limiting what readers can verify.'],['Who will hold the restricted evidence and issue corrections?']),
        ['Consent and version history become part of the research record.','A refusal leaves another route to investigate and does not cancel promised aid.'],
        'If the witness declines all publication, use their account only within the agreed private audience and continue independent records work.',
        ['No persuasion check converts a refusal into consent.'],
        [N('Consenting witness','Retain control over a personally costly account.','The event they experienced and their present risks.','A specific, revocable publication agreement where feasible.','Cannot undo information already heard; future sharing can still be limited.')])
      ],{city:['Mending Court','Lantern House','Second Margin'],dungeon:['Any return with a verified research result'],sites:['silent-library','scar'],mystery:['family-identity-open','district-coupling','district-expansion','district-interventions']},
      'A publication plan that serves actual needs and records whose risks and permissions shaped it.',
      'Donavan can remain a private researcher and provide a narrow practical warning through a trusted intermediary.',
      ['Do not require publication as the moral victory.','Dianna retains opinions and independent work; no father conspiracy is introduced.']),

    C('donavan',5,'The Published Record','resolution',
      'A result has passed review and Donavan chooses whether, when and how to share it.',
      'Release, redact, delay or correct a record, then show a concrete response from its readers.',[
      S('Before the copy leaves','The final page lists contributors, methods, limits and the date. There is one blank line: who receives this version?',
        'Review the exact evidence, rejected predictions, permissions and recipients. Offer a public finding, restricted methods, an embargo with review date, or a private archive. Separate claims of observed reconstruction from proof of an original soul; unresolved identity stays explicit.',
        ['Approve a useful public account with a correction address.','Release a limited version and keep hazardous methods restricted.','Delay publication and preserve an auditable record for future review.'],
        E(['The approved text and actual recipient list.'],['Contributors endorse only the claims they can support.'],['The record supports a bounded decision, not omniscience.'],['What new evidence would require a correction?']),
        ['Publication becomes an explicit reviewed event and only chosen audiences receive it.','Credit and redaction choices affect specific relationships without awarding universal fame.'],
        'A letter to a small group or a privately witnessed archive deposit can resolve the chapter without a book launch.',
        ['No check turns an unsupported conclusion into a publishable fact.'],
        [N('Independent reviewer','Keep the record checkable and its uncertainty visible.','The submitted sources and method.','A way for later readers to distinguish editions.','Does not certify metaphysical claims beyond the evidence.')]),
      S('The useful correction','A reader sends a note: one detail does not match their records. Dianna has underlined the question, not your name. “This could make the next version better.”',
        'Choose a correction supported by a new source, or a genuine reader use if no discrepancy arises. The rival may supply a missing control with credit. Let Donavan acknowledge error, explain the disagreement or withhold judgment while checking. Show one person helped by a practical finding.',
        ['Issue a dated correction and preserve the earlier version.','Invite a repeat with the new source.','Explain why the new claim remains unverified without dismissing the reader.'],
        E(['The new source or actual use of the published warning.'],['The reader reports a discrepancy or benefit.'],['Knowledge can improve without making prior honest work worthless.'],['What question does Donavan choose next?']),
        ['A correction changes approved claims through review rather than silently rewriting history.','His future can include teaching, fieldwork, home life or another choice.'],
        'If nothing was published, a private peer review or an ordinary conversation with Dianna offers the same chance to choose future work.',
        [],[N('Dianna Kemp','Build a shared life while pursuing work she values.','The versions and news actually shared with her.','An honest response and a future they can discuss.','She cannot choose Donavan’s career or promise the mystery is finished.')])
      ],{city:['Mending Court','Second Margin'],dungeon:['After a chosen research or intervention outcome'],sites:[],mystery:['glass-contradictions','family-identity-open','district-interventions']},
      'A defensible record, credited collaborators and a future question chosen by Donavan.',
      'Preserve a private record and let his contribution be a useful warning or a carefully kept promise.',
      ['No compulsory fame, disclosure or permanent rift with the rival.','Open player-held family details remain unfilled.']),

    C('ringgo',1,'A Proper Contract','aftermath',
      'A person actually helped or a legitimate client offers work; suitable in Phandalin or the first Portal contract.',
      'Make investigative and protective skill valuable through explicit terms and an honest deliverable.',[
      S('The work written plainly','The client points to three lines: the question, the payment, and what counts as delivery. “Tell me what you can establish. I am paying for that, not a story I already want to hear.”',
        'Use a modest security survey, missing-goods inquiry with owner consent, or Ilvara’s bounded route contract. Agree fee, permitted access, information privacy, expenses and what a partial result earns. Do not presume the client was rescued or already trusts Ringgo.',
        ['Accept a bounded investigation with an honest-failure clause.','Offer a safer, cheaper scope.','Decline and recommend another worker.'],
        E(['The written terms and accepted scope.'],['The client describes the problem from their perspective.'],['The account suggests leads, not a culprit.'],['Who can independently confirm the loss or risk?']),
        ['An accepted contract creates a real promise and no automatic payment.','Fair negotiation can establish a reference even when the job is narrowed.'],
        'If the party is traveling immediately, make this later downtime work or fold the survey into a route they already need.',
        ['Persuasion can affect an optional fee or deadline; no roll substitutes for informed agreement.'],
        [N('Legitimate client','Resolve a practical problem without unnecessary harm.','Their own property, concern or commission.','A reliable account and agreed discretion.','Does not know Ringgo’s history unless he shares it.')]),
      S('Bring back what is true','You have a useful answer and a boundary: this much is verified; beyond it, the route or account remains unchecked. The client waits for your report.',
        'Resolve a genuine investigative task using current terrain and witnesses. Let Ringgo identify a secure route, recover authorized records, or explain why a claim could not be verified. Offer a receipt and reference only for work actually delivered and payment actually made.',
        ['Deliver the checked finding with its limits.','Arrange a peaceful return of property with a witness.','Report a hazard and recommend postponing the dangerous part.'],
        E(['The inspected route, record or agreed handover.'],['A witness gives a bounded account.'],['The conclusion follows only from checked evidence.'],['What remains outside the contract?']),
        ['The client can offer a specific reference based on observed work.','A nonviolent solution earns the agreed reward without extra kills or confession.'],
        'If the target evidence is unavailable, an honest partial report and safe next step can fulfill the bounded contract.',
        ['Investigation DC 12 can find an extra inconsistency; the agreed core inspection is not removed by one failed roll.'],
        [N('Client or receiving witness','Close the task and keep a useful working relationship.','The delivered evidence and their own agreement.','An understandable record of what is resolved.','A reference is local testimony, not a universal pardon.')])
      ],{city:['Reed & Ledger','Yawning Portal'],dungeon:['A Map Worth Paying For; actual reconnaissance or retreat route'],sites:['wave-echo'],mystery:[]},
      'Agreed pay, if earned and recorded, and a credible reference for legitimate work.',
      'Offer protective reconnaissance or a later fair commission. Declining employment does not force a criminal job.',
      ['No invented rescue or payment.','Ringgo’s class does not dictate morals or methods.']),

    C('ringgo',2,'Someone from Before','waterdeep',
      'After Ringgo’s player accepts an old-contact invitation and chooses the shared history that is safe to establish.',
      'Hear a present request from a former associate without making their history a surprise public reveal.',[
      S('A message with a boundary','The message asks for a meeting, gives a way to refuse, and contains one old detail you can choose to recognize. It does not name your former work to anyone else.',
        'Before play, offer Ringgo’s player the contact’s role, not a fixed identity. Ask whether the relationship was close, professional or barely known; leave anything declined unestablished. The contact wants to leave former work and requests safe transport, records recovery or an introduction.',
        ['Meet privately with a companion of Ringgo’s choosing.','Ask for the present request in writing.','Decline the personal history but hear a new client’s problem.'],
        E(['The message and agreed recognition detail.'],['The sender claims to need a safe exit.'],['The request may be sincere; its full cause is unverified.'],['Who else is affected, and what would make help safe?']),
        ['A chosen meeting establishes only the shared past Ringgo’s player accepts.','A companion learns only the details actually disclosed.'],
        'If Ringgo’s player rejects the hook, use an unrelated client with the same practical need and no retconned history.',
        ['No Insight roll reveals a complete past or proves sincerity.'],
        [N('Ringgo’s old contact, identity to be established','Leave work that has become untenable.','Their own request and the history Ringgo’s player permits.','A hearing and a practical exit.','Not automatically Mara’s colleague, a former handler, or Halaster’s agent.')]),
      S('What help would mean','“I am asking for a place to sleep and someone to look at the papers,” the visitor says. “If the answer is no, tell me before I make another promise.”',
        'Present a specific immediate need, one supporting document and one visible gap. Let Ringgo offer temporary help without endorsing the whole account. The contact may consent to an independent records check. Keep any pursuit rooted in an actual grievance or coercive demand still to investigate.',
        ['Offer limited shelter with a clear duration and no further recruitment.','Arrange a neutral records review.','Provide a safe referral while refusing direct involvement.'],
        E(['The document and specific aid requested.'],['The contact describes who is pursuing them and why.'],['The gap merits checking, not a verdict of betrayal.'],['What part of the account could another person verify?']),
        ['Agreed help becomes a bounded promise.','Refusal changes available assistance without triggering an automatic ambush or death.'],
        'A neutral intermediary can receive the papers if Ringgo wants distance; the contact retains responsibility for their choices.',
        ['Investigation DC 13 can identify a missing signature or amount; the visible gap is clear without a roll.'],
        [N('Ringgo’s old contact','Find immediate safety without returning to the same work.','Their papers and actions, including something not yet disclosed.','Practical help before accepting broader accountability.','Their fear does not make every allegation true; they cannot demand unconditional loyalty.')])
      ],{city:['Yawning Portal','Reed & Ledger','Mending Court'],dungeon:['Terms of Passage return; Skullport only after earned access'],sites:[],mystery:[]},
      'A player-approved relationship and a specific, reviewable promise or referral.',
      'Use a new client, written contact or a boundary respected. The chapter can end with no continuing obligation.',
      ['No compulsory public confession or retroactive handler.','Do not make Mara’s employer the pursuer by default.']),

    C('ringgo',3,'The Part They Left Out','depths',
      'Ringgo chooses to verify the contact’s account or an independent grievance reaches a legitimate inquiry.',
      'Discover an omission that matters while keeping protection and accountability compatible.',[
      S('The other copy of the debt','The second ledger records a name absent from the first: someone who lost goods or wages when the arrangement ended. It does not say that threats against the contact are justified.',
        'Prepare one concrete omission appropriate to the accepted history: an unpaid wage, entrusted property, a false claim or a broken promise. Keep it proportionate; do not spring an unapproved atrocity into the contact’s backstory. An independent claimant can provide a receipt or witness.',
        ['Compare both ledgers and invite corrections.','Hear the claimant separately before confronting the contact.','Protect immediate safety while suspending a broader promise.'],
        E(['The records differ on a specific obligation.'],['Each party describes the loss and their role.'],['A real grievance may coexist with coercive pursuit.'],['What remedy does the affected person actually want?']),
        ['The finding can change the help plan without cancelling emergency safety.','Record contradictory accounts separately until resolved.'],
        'If records are lost, a neutral witness can establish one bounded part; uncertain details remain questions.',
        ['Investigation DC 13 can reconcile dates; no roll makes the harmed person forgive or the contact confess.'],
        [N('Affected claimant','Recover a concrete loss and be heard.','Their own agreement, damage and evidence.','Restitution, correction or safe closure.','Cannot justify unrelated violence or speak for every harmed person.')]),
      S('A chance to answer','The contact reads the missing line. “I hoped that part would stay behind me.” There is space for an explanation, and space for the other person to reject it.',
        'Let the contact explain without predetermining absolution. They may admit, dispute or produce a new record. Ringgo chooses which help remains unconditional and what requires restitution or truthful testimony. Keep credible nonviolent options visible.',
        ['Offer mediation with separate safety arrangements.','Require corrected records before further professional help.','Refuse the disputed work while maintaining a safe referral.'],
        E(['The response and any new corroborated material.'],['The contact explains their omission.'],['Accountability may require several steps rather than one apology.'],['Which terms can each person realistically keep?']),
        ['A revised agreement can preserve life and acknowledge harm.','A refusal by either party leaves an unresolved dispute, not a required combat encounter.'],
        'If direct contact is unsafe or unwanted, use separate messages through a consenting intermediary.',
        ['Persuasion may help arrange a hearing; it cannot override safety boundaries or determine guilt.'],
        [N('Ringgo’s old contact','Keep help while avoiding a feared consequence.','Their own actions and what they withheld.','A possible path forward that is not another coercive contract.','May face accountability even if Ringgo understands their fear.')])
      ],{city:['Reed & Ledger','Lantern House'],dungeon:['Skullport records or suppliers only where actual routes permit'],sites:['silent-library'],mystery:['district-interventions']},
      'A fuller account and a practical path that distinguishes protection from endorsement.',
      'Ringgo can refer the dispute to a trusted mediator and pursue legitimate work elsewhere without a forced betrayal.',
      ['Do not assume every pursuer is evil or every grievance valid.','No compulsory assassination or forgiveness.']),

    C('ringgo',4,'Help with Conditions','depths',
      'A verified need and willing participants make a concrete protection or restitution plan possible.',
      'Use investigation, logistics and chosen boundaries to make an exit real.',[
      S('A plan with names beside it','The plan lists who carries the papers, who checks the destination, and who can call it off. Nobody’s name is written in a space they have not accepted.',
        'Choose a proportionate plan: recover records with owner consent, escort a willing witness, return property after ownership checks, or negotiate release from a coercive arrangement. Use actual routes and room keepers. Offer costs and the chance to narrow the task.',
        ['Arrange a witnessed release with an independent copy.','Help make restitution while keeping the person physically safe.','Provide skills or contacts without joining the entire journey.'],
        E(['The accepted plan, parties and checked route.'],['Each party states what they can deliver.'],['A written release matters only if practical leverage is removed.'],['Who still holds documents, money or threats that could restart the coercion?']),
        ['Agreed obligations become reviewable promises with real holders.','The plan can succeed through negotiation and evidence instead of killing a pursuer.'],
        'If institutions are unsafe, use community witnesses and a smaller voluntary agreement; lawful work need not mean blind trust in officials.',
        ['Use Stealth, Investigation or social checks only for a chosen uncertain step; announce the risk and an alternate approach.'],
        [N('Neutral mediator or route keeper','Keep an enforceable agreement and avoid new harm.','The terms and local conditions they can verify.','Clear consent, responsibilities and a response to breach.','Cannot erase unaddressed harms or guarantee safety outside their reach.')]),
      S('Check the promise in practice','The signed page is ready. Ringgo can still ask one more question: “What stops this from beginning again tomorrow?”',
        'Verify that a returned item changed hands, copies were accounted for, a destination accepted the guest, or a creditor acknowledged the agreed settlement. An honest missing piece becomes follow-up. Let the helped person choose their next step without requiring gratitude.',
        ['Verify the material handover and retain a permitted receipt.','Arrange a check-in with a safe contact chosen by the person.','Stop at the agreed limit and document what remains unresolved.'],
        E(['The actual transfer, arrival or changed access.'],['Participants report whether agreed terms were fulfilled.'],['Reduced leverage supports a safer exit without guaranteeing a perfect future.'],['What unresolved claim or danger should remain visible?']),
        ['The chapter can record a real rescue, debt adjustment or promise completed through review.','An antagonist may survive and a harmed person may withhold forgiveness.'],
        'A partial result with a safe withdrawal can close the immediate job; preserve unfinished terms for later choice.',
        ['No single roll declares every copy destroyed or every future threat ended. Inspect only what is actually accessible.'],
        [N('Person receiving help','Choose a workable life beyond the immediate danger.','Their own needs and the help delivered.','Autonomy and clear next contacts.','Does not owe friendship, secrecy or absolution in return.')])
      ],{city:['Mending Court','Reed & Ledger','Blue Lantern Quay'],dungeon:['A currently known escort or document-recovery route'],sites:['observatory','walking-tower'],mystery:['district-interventions']},
      'A verified safer situation, an earned professional reference and honest unresolved follow-up.',
      'Support a referral or a narrower task. Ringgo is not responsible for every later choice another person makes.',
      ['Do not reward help by making the beneficiary obedient.','Do not automatically merge this local dispute into Looking Glass.']),

    C('ringgo',5,'The Work He Chooses','resolution',
      'After actual contracts or personal decisions give Ringgo a basis for choosing the relationships and work he wants.',
      'Resolve the current obligation and make room for a future defined by present choices.',[
      S('Close the account honestly','The old file is thin enough to read in one sitting: the request, the promises, what was done, and what remains. You can close a job without pretending every wound is closed.',
        'Review actual payment, restitution, safety and unresolved claims. Ask the affected people what they acknowledge, not whether they forgive. Offer a clear completion, limited closure or a continuing commitment with a review date. Keep private history out of public references.',
        ['Close the immediate task and name what remains outside it.','Accept a continuing practical commitment with limits.','End the relationship while honoring outstanding agreed terms.'],
        E(['Verified deliveries, payments and promises.'],['Each participant gives their own account of the outcome.'],['A completed job can support a local reputation for reliability.'],['Which relationships does Ringgo freely want to continue?']),
        ['Approved outcomes can complete the relevant personal step without closing unrelated quests.','A victim’s unresolved feelings remain their own.'],
        'If the old-contact hook was declined, review an ordinary contract and let reliable present work carry the chapter.',
        [],[N('Former client or affected person','Know which obligations remain and which are settled.','The work and harm they actually experienced.','A truthful account and freedom to choose further contact.','Does not grant a universal verdict on Ringgo’s past.')]),
      S('The name on the door','Someone comes looking for help and asks the simplest question: “What sort of work do you take?” This time, you get to answer before there is a bargain.',
        'Offer a future as investigator, escort, security teacher, quiet tradesperson or something Ringgo’s player invents. A modest new commission can test one stated boundary. Ringgo can stay at Mending Court, keep traveling or leave the trade without losing every friendship.',
        ['Define services and limits openly.','Teach protective skills to willing people.','Choose another livelihood and keep only the contacts he values.'],
        E(['The work Ringgo chooses and limits he states.'],['A new client explains their legitimate need.'],['An earned reference opens a conversation, not automatic trust everywhere.'],['What promise would he want his name to mean?']),
        ['End on a specific person helped by his actual skills or reliability.','Future hooks follow the chosen work instead of dragging him back into unwanted history.'],
        'A private conversation with a companion can define the next step if Ringgo does not want a public professional identity.',
        [],[N('New legitimate client','Solve an ordinary problem without hidden terms.','A specific reference or visible example of Ringgo’s work.','An honest yes, no or narrower proposal.','Does not secretly require murder to prove that the past cannot be escaped.')])
      ],{city:['Mending Court','Reed & Ledger'],dungeon:['A future route survey or protective job chosen by Ringgo'],sites:[],mystery:[]},
      'A chosen professional identity and relationships supported by kept promises.',
      'Let the ending be rest, a smaller honest job or a private choice; a public confession is unnecessary.',
      ['No mandatory retirement, confession or forgiveness.','Skills and class features remain the player’s tools, not a moral verdict.']),
    C('aldric',1,'The Ring and the Record','waterdeep',
      'Only when Aldric chooses a discreet inquiry, beginning with an existing impression or a voluntary examination of the signet.',
      'Establish identity through two independent records while keeping Crown geography, family names and private history open.',[
      S('A copy without a sacrifice','The specialist moves the lamp, not your hand. “We can draw what remains. Nothing here requires taking the ring off.”',
        'Obtain permission for a sketch or non-invasive impression. Ask what may be recorded, copied and retained. Compare the scorched crest and one distinctive surviving repair or commission feature only if Bowman accepts that detail. A match can identify a design or office, not guilt or a complete biography.',
        ['Keep the copy private and request a catalogue comparison.','Permit one trusted companion to witness without wider explanation.','Decline examination and use a signature or existing record instead.'],
        E(['The voluntarily recorded features of the actual ring.'],['A specialist proposes a maker or office classification.'],['A design match is a lead to identity, not proof of its wearer.'],['Which independent appointment or commission record could corroborate it?']),
        ['A permitted copy can become an owner-only research lead.','The ring remains on Aldric’s finger; no injury, removal or magic benefit is required.'],
        'A known signature, an old witness or an authenticated appointment entry offers another route if he keeps the ring private.',
        ['History or relevant tools DC 13 narrows catalogue work; a failed check leads to a slower specialist search.'],
        [N('Independent records specialist','Identify a damaged object accurately while respecting a client’s privacy.','Their catalogue and the features Aldric permits them to inspect.','A narrow question, fee and copying permission.','Cannot infer Crown crimes, family names or magical ownership from a crest.')]),
      S('Two records, two keepers','One record describes a commission. The other lists an appointment. They agree on one identifying detail, but they were kept by different people for different reasons.',
        'Prepare separate provenance: maker’s commission and civic or office appointment record. Set names and Crown details with Bowman before presenting them. A match can establish a bounded fact about Aldric’s former office. Retain inconsistencies and gaps; nothing restores memory automatically.',
        ['Authorize a limited comparison under a private name.','Ask how each record survived and who copied it.','Stop after the identity question and postpone the personal history.'],
        E(['Two authenticated records and their matching identifying detail.'],['An archivist explains each record’s custody.'],['The match supports an office-holder identity within the records’ limits.'],['Who knew the person beyond official paperwork?']),
        ['A reviewed finding can support a voluntary witness lead.','Aldric decides which companions receive the result.'],
        'If one record is inaccessible, keep the identification provisional and seek an independently preserved signature or testimony.',
        ['Investigation DC 14 identifies a copy-chain gap sooner; accessible core entries remain available.'],
        [N('Keeper of the independent appointment record','Protect a collection and avoid false identification.','The record’s wording, provenance and missing pages.','A defensible comparison and safe handling.','Does not know whether the office-holder deserved praise or condemnation.')])
      ],{city:['Second Margin','Reed & Ledger'],dungeon:['A records lead offered after Terms of Passage'],sites:['silent-library'],mystery:['aldric-restoration']},
      'One corroborated identity fact, a private source trail and control over the next inquiry.',
      'Keep the inquiry dormant. Aldric can make a present-day contribution without exposing his past.',
      ['Bowman retains Crown and family details until established.','The signet is an identifying anchor, never a soul cage or obedience device.']),

    C('aldric',2,'Someone Who Remembers','waterdeep',
      'After a credible witness lead and separate consent from Bowman and the prospective witness; hold the meeting during a city return.',
      'Hear one corroborable account of a Crown act and offer practical help without buying forgiveness.',[
      S('A meeting with an exit','The intermediary explains the arrangements first: where the doors are, who may attend, and that either person can end the meeting. There will be no demand for an apology accepted on command.',
        'Keep the witness’s identity a role until agreed. They survived or directly documented one specific Crown act, not Aldric’s entire life. Give them a current occupation and need chosen for this encounter. Offer written testimony, a screened meeting or no meeting. Use a neutral place; do not ambush Aldric at home.',
        ['Hear a written account before choosing contact.','Meet with an agreed supporter and time limit.','Respect a refusal and pursue independent records.'],
        E(['The meeting terms and any voluntarily supplied record.'],['The witness describes the specific event they experienced.'],['Their account may connect Aldric to one act, pending corroboration.'],['What independent civilian or administrative record survives?']),
        ['A safe meeting can begin a relationship without reconciliation.','Refusal leaves a records route and never cancels promised practical aid.'],
        'An intermediary can preserve testimony for later review. The witness is not punished for declining.',
        ['No Insight or Persuasion roll forces trauma disclosure or forgiveness.'],
        [N('Crown survivor or civilian witness, identity to be established','Protect a life built after a specific harm.','What they directly saw and records they retained.','A present need addressed and control over their testimony.','Not an omniscient judge of Aldric or a disguised Halaster messenger.')]),
      S('The act and the next need','“I can tell you what happened on that day,” the witness says. “What I need now is different.” They place a practical request beside the old record.',
        'Pair one dated detail with an independent source. Let the request be transport to a safe appointment, recovery of verified property, protection of a record, or help for people the witness names with consent. It is not a price for testimony. Aldric can acknowledge responsibility without accepting every unverified allegation.',
        ['Offer practical aid with no demand for secrecy or absolution.','Investigate the disputed detail before making a public statement.','Make a limited commitment and say honestly what cannot be promised.'],
        E(['A corroborated dated detail and any aid actually delivered.'],['The witness states the effect the act had on them.'],['One repaired harm does not balance all past harms.'],['What aid do affected people want, and who else should be heard?']),
        ['Approved aid and historical findings become separate records.','The witness may accept help and still distrust or dislike Aldric.'],
        'If direct aid is declined, respect the answer and offer an appropriate institution or anonymous contribution without claiming it earned forgiveness.',
        ['Investigation can corroborate the event; it does not make a remembered feeling equivalent to an external record.'],
        [N('Crown survivor or civilian witness','Meet a current practical need without surrendering their account.','One bounded event and its personal consequences.','A choice that remains theirs.','Cannot grant forgiveness on behalf of others or prove the fate of Aldric’s family.')])
      ],{city:['Lantern House','Reed & Ledger','Mending Court by invitation only'],dungeon:['Ordinary city return between expeditions'],sites:[],mystery:['aldric-independent']},
      'A checked historical fact, a voluntary relationship or a meaningful act of repair with no promised absolution.',
      'Use records and an intermediary. The campaign proceeds while this personal meeting stays deferred.',
      ['Do not stage graphic flashbacks or dictate Aldric’s emotional response.','Crown crimes remain independent of Halaster; no coerced redemption score.']),

    C('aldric',3,'The Return Ledger','depths',
      'After earned access to relevant research and sufficient pacing for the restoration revelation; no early expedition automatically reveals it.',
      'Corroborate Halaster’s role through records, an independent intermediary and identifying evidence.',[
      S('The record that can be checked','The entry describes a body, a damaged hand, and a signet. Its conclusion is narrow: the subject continued living after departure; memory remained incomplete. The page also records what the writer could not explain.',
        'Place the custom record only in a compatible, prepared research context; do not rewrite a published room. Verify handwriting, dating and custody through separate samples. Include enough identifying detail for Aldric to compare privately. The record describes identifiable remains and a recoverable soul, unlike the family’s failed retrievals.',
        ['Authenticate the record before confronting its author.','Copy only the relevant entry with permission or lawful access.','Seek a separate intermediary who handled the remains or witnessed the return.'],
        E(['The authenticated entry and matching physical detail, if verified.'],['The writer claims a return experiment succeeded with incomplete memory.'],['Aldric may be the subject; the claim needs independent corroboration.'],['Who witnessed transfer or departure independently of this record?']),
        ['The record becomes one source family, however many copies exist.','Aldric chooses who may inspect his identifying details.'],
        'A permitted archival copy and an independent practitioner can establish the lead without an audience with Halaster or a satellite visit.',
        ['Arcana and Investigation can assess method and provenance; no single roll confirms every statement in the ledger.'],
        [N('Research custodian or former assistant','Keep a defensible record and avoid repeating an unsafe experiment.','One laboratory record and its custody.','Clear limits on copying or further use.','Cannot infer family-soul identity or claim ownership of Aldric.')]),
      S('A witness who was not in the room with the author','The intermediary describes the transfer before seeing your copy. One detail matches. Another is something the ledger never mentioned. “I can tell you what I carried and where I left it. I cannot tell you everything he did afterward.”',
        'Use an independent intermediary or attendant whose knowledge is bounded and source chain recorded. Establish how their account can be checked without fixing the Crown’s location or every missing year. Only after record, witness and identifying match support it, confirm Halaster’s role. Any ownership claim is his attitude, not a magical contract.',
        ['Compare accounts and preserve remaining gaps.','Request records without accepting a debt to Halaster.','Refuse direct contact and retain independent proof.'],
        E(['Independently matched transfer or departure details.'],['The intermediary describes their limited participation.'],['Together, the sources support Halaster’s role in Aldric’s return.'],['Which missing steps remain unknown, and does further inquiry serve Aldric?']),
        ['A reviewed conclusion can establish the return’s cause without obligating cooperation.','The record explicitly distinguishes Aldric’s continued independent life from the machine’s operation.'],
        'If a witness is unavailable, obtain another independently held transport or care record and keep the conclusion provisional until enough evidence exists.',
        ['No coercive memory test or deliberate injury is required to demonstrate independence.'],
        [N('Independent return intermediary, identity to be established','Explain a limited past role without being made responsible for all of Halaster’s work.','The remains or subject they personally handled and a checkable detail.','An agreed audience and protection from misuse of their account.','Does not know why the Crown acted, every experiment step or the fate of Halaster’s family.')])
      ],{city:['Second Margin','Lantern House'],dungeon:['Later prepared research access; no guaranteed published room placement'],sites:['silent-library','walking-tower'],mystery:['aldric-restoration','aldric-independent','family-identity-open']},
      'Corroborated knowledge of the return and a clear basis for rejecting a claimed debt or dependency.',
      'Keep the lead private or use an independent copied record. Aldric’s story and existence continue if he never meets Halaster.',
      ['Halaster did not order Aldric’s execution or family murders.','Destroying or stopping Looking Glass cannot switch Aldric off; the ring is not a control mechanism.']),

    C('aldric',4,'Their Names, Their Lives','depths',
      'Bowman wants to develop family details and a credible personal archive or consenting witness can preserve them.',
      'Recover ordinary lives through independent relationships, leaving magical reunion and complete memory unpromised.',[
      S('The record outside the office','This page was not written for a magistrate. It concerns an ordinary purchase, an invitation, or a family favor. For once, the person at its center was doing something that had nothing to do with the Crown.',
        'Agree names and one ordinary detail with Bowman before preparing the document. Use a letter, household receipt or friend’s keepsake with a plausible chain of custody. It reveals a chosen fact about his wife or child, not a surprise secret destiny. Let Aldric stop, read privately or ask someone to read it with him.',
        ['Preserve a copy and ask about its ordinary context.','Share one chosen detail with a trusted companion.','Leave the original with its willing keeper and return another day.'],
        E(['The authenticated personal record and its named details.'],['The keeper explains how it reached them.'],['An ordinary relationship can be established without restoring a memory.'],['Who knew them independently, and what did they value?']),
        ['One player-approved family fact can enter private continuity.','Aldric may feel recognition, grief, nothing or another response chosen by Bowman.'],
        'If Bowman prefers to keep names open, preserve an unnamed personal detail or focus on a present relationship instead.',
        ['No Wisdom or Intelligence check dictates emotion or awards complete autobiographical recovery.'],
        [N('Keeper of a personal record','Honor people whose lives extended beyond official history.','The record’s provenance and one ordinary connection.','Permission to preserve the memory without turning it into spectacle.','Does not know every family detail or promise contact with the dead.')]),
      S('Someone remembers something small','The witness describes a habit no official file would need to record. Then they ask whether you want to hear more. The answer can be yes, later, or no.',
        'Use a family friend, independently preserved correspondence or a descendant’s inherited account whose limits are clear. Check a mundane detail against the first record before accepting it as corroboration. The witness has their own life and may remember an imperfect person, not a saint. Compare Halaster’s approach only if Aldric chooses.',
        ['Hear another ordinary story and preserve its source.','Ask what act of remembrance would help a living person.','Choose to stop pursuing memories and honor the known facts.'],
        E(['The checked overlap between independently preserved accounts.'],['The witness’s personal memory or attributed family account.'],['A partial history can be meaningful without proving every detail.'],['What does Aldric want to carry forward rather than recreate?']),
        ['A memorial, returned keepsake or consented archive can become a concrete personal outcome.','No one offers a guaranteed family resurrection as the reward.'],
        'A second private record can serve if a living witness is impossible; label copied family stories as one source family.',
        ['History can locate context; it cannot verify a story solely because it feels familiar.'],
        [N('Family witness or keeper of independent correspondence','Preserve a person’s actual life and retain their own boundaries.','One relationship or independently received account.','A respectful exchange, not a forced reunion performance.','Identity and connection remain agreed with Bowman; no hidden link to Halaster’s family is assumed.')])
      ],{city:['Second Margin','Mending Court by invitation'],dungeon:['A provenance lead from a later expedition, followed in the city'],sites:['silent-library'],mystery:['aldric-independent','family-ilyra-tavin','family-identity-open']},
      'Player-approved family history, a meaningful keepsake or act of remembrance, and the right to stop searching.',
      'Let known feelings remain unnamed and build a present relationship. The main mystery has independent evidence routes.',
      ['Aldric’s family are not substitutes or secret relatives for Ilyra and Tavin.','Do not fix family names, homeland, complete memories or a magical reunion without Bowman.']),

    C('aldric',5,'A Life of His Choosing','resolution',
      'Aldric has a concrete chance to repair harm or decide his response to Halaster, at a scale supported by actual play.',
      'Choose a present responsibility and a future without making life, forgiveness or identity a bargain.',[
      S('The help that is wanted','The request is specific: preserve these records, escort this person, return what belongs to them, or make this place safer. Nobody asks you to become the person you were.',
        'Offer one practical act chosen by affected people, with consent, cost, scope and a credible end. It may concern Crown harm or a present neighborhood risk. Aid does not depend on testimony, public confession or accepting Aldric’s explanation. Let the party help without making him a sacrifice.',
        ['Accept a bounded act of repair and ask what success means to the recipient.','Protect testimony while acknowledging his own verified role.','Offer a different useful contribution within his capacity.'],
        E(['The actual need, accepted terms and delivered aid.'],['Affected people describe their preferred remedy.'],['A kept promise can reduce one harm without cancelling the past.'],['What responsibility is sustainable after the immediate crisis?']),
        ['Record the practical result independently of anyone’s forgiveness.','A smaller kept promise can complete the chapter if the larger campaign remains unfinished.'],
        'If the proposed recipients decline contact, respect it and choose another legitimate act without claiming to have repaired their harm.',
        ['Use the actual task’s risks and rules; no moral score or final redemption roll.'],
        [N('Person or community receiving aid','Address a current need on their own terms.','Their own harm and the help offered.','A specific useful result and autonomy afterward.','Cannot absolve Aldric for everyone or demand that he surrender his independent life.')]),
      S('An answer that does not ask permission','When the question of debt returns, there is an answer available that needs no spell to enforce it: “You had a part in my return. You do not get to decide what I do with it.”',
        'Use this as an optional line Aldric may change or reject. Offer direct dialogue, a written refusal, bounded cooperation, or no contact with Halaster. Any technical intervention requires actual tested safeguards; Aldric’s life is never its collateral. End with an ordinary chosen future: study, service, family remembrance, friendships or travel.',
        ['Refuse any claimed ownership and choose an independent future.','Negotiate specific assistance with clear stop conditions and no life-debt.','Avoid Halaster and act through trusted allies or independent records.'],
        E(['Aldric’s stated boundaries and Halaster’s observed response, if encountered.'],['Halaster may claim success or entitlement.'],['Useful evidence does not create an obligation of obedience.'],['What does Aldric want to build beyond investigating his return?']),
        ['The selected response becomes a relationship outcome only after play.','No apparatus shutdown removes Aldric’s existence or automatically restores memory.'],
        'If the return’s cause remains unresolved, let Aldric define a present purpose without knowing every answer.',
        ['No Charisma check is needed to retain agency. Persuasion can affect a negotiation, not the ownership of a person.'],
        [N('Halaster Blackcloak, if contact is chosen','Use a surviving result to support his renewed experiment.','His own work and what he has actually observed.','Evidence or cooperation that might validate his theory.','His entitlement is a claim; he did not cause the Crown crimes and cannot switch Aldric off.')])
      ],{city:['Mending Court','Lantern House'],dungeon:['A player-chosen later audience or independent intervention'],sites:[],mystery:['aldric-independent','aldric-restoration','district-interventions']},
      'A concrete act of repair and a future chosen by Aldric, with identity and life independent of the experiment.',
      'A present-day promise, quiet memorial or new relationship can close the personal chapter without a confrontation.',
      ['No required sacrifice, forgiveness, complete memory or resurrection of family.','The original souls of Ilyra and Tavin remain unconfirmed; Aldric’s case does not prove their return possible.']),
  ];
  globalThis.ECHO_CHARACTER_CHAPTERS_DATA={version:1,chapters,principles:[
    'Every chapter is private future preparation. Begin from approved events; no chapter seeds knowledge, completes an objective, moves an item or spends resources.',
    'Choose one or two opportunities for an expedition and rotate attention using offered, played, deferred and declined spotlight records. A character may contribute without revealing a personal secret.',
    'Accessible core evidence has another credible source. Checks change time, exposure or extra detail; no single roll erases the only lead.',
    'Separate observed facts, attributed claims, provisional inferences and open questions. Record source independence, consent and the exact audience before publication.',
    'Published room keys and current dungeon inhabitants remain authoritative. Place a custom hook only after checking the actual route and persistent room state.',
    'Names and connections still reserved for players remain roles until agreed: the missing craftsperson, scholarly rival, Ringgo’s old contact, Crown details, and Aldric’s family.',
    'Quests may advance through negotiated limits, refusal, retreat, partial information or a smaller act of care. Refusing a personal hook never blocks the main campaign.'
  ]};
})();
